const inp = $input.first().json;
const REQUIRED = ['userId','sessionId','remoteJid','instance'];
const missing  = REQUIRED.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { success: false, error: 'MISSING_FIELDS', details: missing } }];
}
return [{ json: { success: true, ...inp } }];

// Siempre cargamos todos los destinos activos.
// Son 10 filas estáticas — costo de query mínimo.
return [{ json: { operation: 'getDestinations', params: {} } }];

// Cargar cotizaciones existentes del usuario si hay alguna.
// Las cotizaciones pueden venir de SAGE o ser ingresadas manualmente en ATLAS.
const inp = $('🔍 Validar Input ATLAS').first().json;
return [{ json: { operation: 'getQuotes', params: { userId: inp.userId } } }];

// ============================================================
// ATLAS v1.0.0 — Consejero de Turismo Médico
// Sistema NOVA · SAGE · ATLAS + WhatsApp
// Erick Del Piero | Marzo 2026
//
// MOTOR DE ESTADO:
//   welcome / handoff_received  → Bienvenida + ¿tiene cotizaciones?
//   has_quotes_check            → Routing: tiene/no tiene cotizaciones
//   exploring                   → Modo exploración: panorama de destinos
//   entering_quotes             → Usuario ingresa cotizaciones manualmente
//   analyzing                   → Cálculo de costo total por destino
//   comparison_done             → Análisis mostrado, ofrecer checklist
//   checklist_shown             → Checklist pre-viaje entregado
//
// CÁLCULO DE COSTO TOTAL:
//   Total = procedimiento + vuelo estimado + (hotel/noche × días recuperación)
//
// DISEÑO PARA CLAUDE UPGRADE:
// El parsing de cotizaciones del mensaje (precio + destino) será
// reemplazado por Claude NLP. El cálculo y la generación del
// análisis comparativo también se beneficiarán de Claude para
// respuestas más personalizadas y narrativas.
// ============================================================

const inp         = $('🔍 Validar Input ATLAS').first().json;
const destResult  = $('🗄️ DB — Cargar Destinos').first().json;
const quotesResult = $input.first().json; // resultado del DB quotes

// ── SETUP ──────────────────────────────────────────────────
const ctx   = inp.sessionContext || {};
const atlas = { ...(ctx.atlas || {}) };
const sage  = ctx.sage  || {}; // contexto de SAGE si existe
const state = atlas.state || 'welcome';
const txt   = (inp.messageText || '').toLowerCase().trim();
const fn    = inp.userName ? inp.userName.split(' ')[0] : null;
const nm    = fn ? ` ${fn}` : '';

// Datos de destinos desde DB
const destinations = (destResult.success && destResult.data) ? destResult.data : [];
// Cotizaciones existentes en DB
const dbQuotes     = (quotesResult.success && quotesResult.data) ? quotesResult.data : [];
// Cotizaciones locales en contexto (ingresadas en esta sesión)
const localQuotes  = atlas.quotes || [];
// Unir: DB primero (más completas), luego locales que no tengan equivalente
const allQuotes    = dbQuotes.length > 0 ? dbQuotes : localQuotes;

// Tipo de procedimiento (heredado de SAGE si disponible)
const procType = atlas.procedure_type || sage.specialty || 'dental';
const recoveryField = procType === 'dental' ? 'avg_recovery_days_dental' : 'avg_recovery_days_plastic';

// Helper de formato
const usd = (n) => {
  const num = parseFloat(n) || 0;
  return `$${num.toLocaleString('en-US', {minimumFractionDigits:0, maximumFractionDigits:0})} USD`;
};

let rt  = '';         // responseText
let nag = 'ATLAS';   // newActiveAgent
let nss = 'atlas_active'; // newSessionState

switch(state) {

  // ── BIENVENIDA ─────────────────────────────────────────────
  case 'welcome':
  case 'handoff_received': {
    const procName = sage.procedure_name ? `\n\nVeo que SAGE preparó tu solicitud de *${sage.procedure_name}*. ` : '';
    rt = `Hola${nm}, soy *ATLAS* 🗺️, tu consejero de turismo médico de Pangi.${procName}\n\nMi especialidad es calcular el *costo total real* de tu viaje médico: procedimiento + vuelo + alojamiento + días de recuperación.\n\nTengo datos actualizados de *10 destinos* en Latinoamérica y USA.\n\n*¿Ya tienes cotizaciones de médicos para comparar?*\n\n1️⃣ *Sí, tengo cotizaciones* — Calculo el costo total por destino\n2️⃣ *No tengo aún* — Te muestro un panorama general de destinos\n\nEscribe 1 o 2.`;
    atlas.state = 'has_quotes_check';
    atlas.procedure_type = procType;
    break;
  }

  // ── ¿TIENE COTIZACIONES? ────────────────────────────────────
  case 'has_quotes_check': {
    const hasQ  = /^[s1si]$|s[íi]|tengo|yes|cuento/.test(txt);
    const noQ   = /^[n2no]$|no |todavía|aun|explorar/.test(txt);

    if (hasQ || allQuotes.length >= 1) {
      if (allQuotes.length >= 2) {
        // Ya tiene cotizaciones en DB — ir directo a análisis
        atlas.state  = 'analyzing';
        atlas.quotes = allQuotes;
        // Recalcular en el siguiente mensaje; aquí confirmamos
        rt = `Perfecto${nm}, encontré ${allQuotes.length} cotizaciones guardadas. Escribe *comparar* para ver el análisis completo de costos totales.`;
      } else {
        atlas.state  = 'entering_quotes';
        atlas.quotes = allQuotes;
        rt = `Perfecto${nm} 📊 Ingresemos tus cotizaciones.\n\n*Formato para ingresar:*\n📝 Escribe: *País - Ciudad - Precio del procedimiento*\n\n*Ejemplo:*\n• Colombia - Medellín - $800\n• México - Cancún - $650\n\nEscribe tu primera cotización.`;
      }
    } else if (noQ) {
      atlas.state = 'exploring';
      if (destinations.length === 0) {
        rt = `Estoy cargando información de destinos${nm}...`;
        break;
      }
      const destLines = destinations
        .filter(d => d.city !== 'Miami')
        .map(d => {
          const rec = d[recoveryField] || 3;
          const total_est = (d.avg_flight_cost_usd || 0) + ((d.avg_hotel_cost_per_night_usd || 70) * rec);
          return `🌎 *${d.city}, ${d.country}*\n   ✈️ Vuelo: ~${usd(d.avg_flight_cost_usd)} | 🏨 Hotel/noche: ~${usd(d.avg_hotel_cost_per_night_usd)} | ⏱️ Recuperación: ${rec} días\n   💰 Costo viaje est. (sin procedimiento): ~${usd(total_est)}`;
        }).join('\n\n');

      rt = `Aquí tienes los principales destinos de turismo médico${nm}:\n\n${destLines}\n\n🇺🇸 *Miami, USA* — precio de referencia local (para comparar cuánto ahorras)\n\n*Para calcular el costo total real* necesitas cotizaciones de médicos.\n\n¿Quieres que te conecte con *SAGE* para preparar tu solicitud? Escribe *sí* o sigue explorando.`;
    } else {
      rt = `Por favor escribe *1* si tienes cotizaciones o *2* si quieres explorar destinos${nm}.`;
    }
    break;
  }

  // ── MODO EXPLORACIÓN ────────────────────────────────────────
  case 'exploring': {
    const wantsSage    = /sage|nueva solicitud/i.test(txt);
    const wantsCompare = /^comparar$|ver comparac|analiz/i.test(txt);
    const wantsEnter   = /cotizac|ingresar|tengo cotizac|1/i.test(txt);

    // Detectar cotización ingresada directamente desde exploración
    // Formato: "País - Ciudad - $Precio" o variantes
    const priceMatch  = txt.match(/\$?([\d][\d,\.]*[\d])\s*(?:usd|dólares?|dolares?)?/i);
    const price       = priceMatch ? parseFloat(priceMatch[1].replace(/,/g,'')) : null;
    const destMatch   = price ? destinations.find(d =>
      txt.includes(d.city.toLowerCase()) ||
      txt.includes(d.country.toLowerCase())
    ) : null;
    const hasQuoteFormat = !!(price && destMatch);

    if (wantsSage) {
      rt  = `¡Perfecto${nm}! Te conecto con *SAGE* 🩺 para preparar tu solicitud.\n\nCuando tengas cotizaciones, regresa con ATLAS para el análisis.`;
      nag = 'SAGE'; nss = 'handoff_received'; atlas.state = 'handoff_to_sage';

    } else if (hasQuoteFormat) {
      // Usuario ingresó cotización directamente sin pasar por entering_quotes
      const quotes = atlas.quotes || [];
      quotes.push({ destination_city: destMatch.city, destination_country: destMatch.country, procedure_cost: price });
      atlas.quotes = quotes;
      atlas.state  = quotes.length >= 2 ? 'entering_quotes' : 'entering_quotes';

      if (quotes.length === 1) {
        rt = `✅ Cotización registrada: *${destMatch.city}* — ${usd(price)}\n\nAgrega al menos una más y escribe *comparar* para ver el análisis de costos totales.`;
      } else {
        rt = `✅ Cotización ${quotes.length} registrada: *${destMatch.city}* — ${usd(price)}\n\nYa tienes ${quotes.length} cotizaciones. Escribe *comparar* para ver el análisis completo.`;
      }

    } else if (wantsCompare) {
      const quotes = atlas.quotes || [];
      if (quotes.length >= 2) {
        // Trigger análisis inmediato
        atlas.state = 'comparison_done';
        const analysis = quotes.map(q => {
          const destData  = destinations.find(d =>
            d.city.toLowerCase() === q.destination_city.toLowerCase() ||
            d.country.toLowerCase() === q.destination_country.toLowerCase()
          );
          const flightCost = parseFloat(destData ? destData.avg_flight_cost_usd : 400);
          const hotelNight = parseFloat(destData ? destData.avg_hotel_cost_per_night_usd : 80);
          const recDays    = parseInt(destData ? destData[recoveryField] : 3);
          const hotelCost  = hotelNight * recDays;
          const totalCost  = parseFloat(q.procedure_cost) + flightCost + hotelCost;
          return { ...q, flightCost, hotelNight, recDays, hotelCost, totalCost };
        }).sort((a, b) => a.totalCost - b.totalCost);

        atlas.analysis        = analysis;
        atlas.best_destination = analysis[0].destination_city;

        const medals = ['🥇','🥈','🥉','4️⃣','5️⃣'];
        const table  = analysis.map((a, i) =>
          `${medals[i]||`${i+1}.`} *${a.destination_city}, ${a.destination_country}*\n   💊 Procedimiento: ${usd(a.procedure_cost)}\n   ✈️ Vuelo: ${usd(a.flightCost)}\n   🏨 Hotel (${a.recDays} noche${a.recDays>1?'s':''}): ${usd(a.hotelCost)}\n   💰 *TOTAL REAL: ${usd(a.totalCost)}*`
        ).join('\n\n');

        const saving = analysis.length > 1
          ? analysis[analysis.length-1].totalCost - analysis[0].totalCost : 0;
        const recText = saving > 0
          ? `✅ *${analysis[0].destination_city}* es la opción más económica, ahorrando *${usd(saving)}* vs la más cara.`
          : `✅ *${analysis[0].destination_city}* es tu mejor opción.`;

        rt = `📊 *Comparación de Destinos — Costo Total Real*\n\n${table}\n\n${recText}\n\nEscribe *checklist* para ver la lista de preparación para viajar a ${analysis[0].destination_city}.`;
      } else {
        rt = `Necesito al menos 2 cotizaciones para comparar${nm}. Tienes ${quotes.length}.\n\nIngresa en formato: *País - Ciudad - $Precio*`;
      }

    } else if (wantsEnter) {
      atlas.state = 'entering_quotes';
      rt = `Listo${nm}. Ingresa tu primera cotización en formato:\n*País - Ciudad - $Precio*\n\nEjemplo: Colombia - Medellín - $800`;

    } else {
      rt = `¿Quieres que te ayude con algo en particular${nm}?\n\n📊 Escribe una cotización — Formato: *País - Ciudad - $Precio*\n📊 Escribe *comparar* — Si ya tienes 2+ cotizaciones\n🩺 Escribe *sage* — Para preparar solicitud de cotización`;
    }
    break;
  }

  // ── INGRESO DE COTIZACIONES ─────────────────────────────────
  case 'entering_quotes': {
    const quotes = [...(atlas.quotes || [])];

    // Detectar si el usuario pide comparar con las que ya tiene
    const wantsCompare = /comparar|analiz|listo|ver|ok|calcula|suficiente/i.test(txt);
    if (wantsCompare && quotes.length >= 2) {
      atlas.state  = 'analyzing';
      atlas.quotes = quotes;
      // Generar análisis inmediatamente
      // Fall-through a 'analyzing' state - usaremos goto pattern
      // (En N8N esto se maneja con el mismo mensaje; el usuario recibirá el análisis)
    }

    // Extraer precio del mensaje
    const priceMatch = txt.match(/\$?([\d][\d,\.]*[\d])\s*(?:usd|dólares?|dolares?)?/i);
    const price      = priceMatch ? parseFloat(priceMatch[1].replace(/,/g,'')) : null;

    // Identificar destino
    const destMatch = destinations.find(d =>
      txt.includes(d.city.toLowerCase())    ||
      txt.includes(d.country.toLowerCase())
    );

    if (!price && !wantsCompare) {
      rt = `No pude extraer el precio de tu cotización${nm}. Usa el formato:\n\n*País - Ciudad - $Precio*\n\nEjemplo:\n• Colombia - Medellín - $800\n• México - CDMX - $1200`;
      break;
    }

    if (price && destMatch) {
      const newQuote = {
        destination_city:    destMatch.city,
        destination_country: destMatch.country,
        procedure_cost:      price
      };
      quotes.push(newQuote);
      atlas.quotes = quotes;

      if (quotes.length < 2) {
        rt = `✅ Cotización registrada: *${destMatch.city}* — ${usd(price)}\n\nAgrega más cotizaciones para comparar, o escribe *comparar* cuando tengas al menos 2.`;
      } else {
        rt = `✅ Cotización ${quotes.length} registrada: *${destMatch.city}* — ${usd(price)}\n\nTienes ${quotes.length} cotizaciones. Escribe *comparar* para ver el análisis, o agrega más.`;
        atlas.state = 'analyzing';
      }
    }

    // Si el usuario quiere comparar y tiene suficientes cotizaciones
    if ((wantsCompare || atlas.state === 'analyzing') && quotes.length >= 2) {
      atlas.state  = 'comparison_done';
      const analysis = quotes.map(q => {
        const destData  = destinations.find(d =>
          d.city.toLowerCase()    === q.destination_city.toLowerCase()    ||
          d.country.toLowerCase() === q.destination_country.toLowerCase()
        );
        const flightCost = parseFloat(destData ? destData.avg_flight_cost_usd          : 400);
        const hotelNight = parseFloat(destData ? destData.avg_hotel_cost_per_night_usd : 80);
        const recDays    = parseInt(destData   ? destData[recoveryField]               : 3);
        const hotelCost  = hotelNight * recDays;
        const totalCost  = parseFloat(q.procedure_cost) + flightCost + hotelCost;
        return { ...q, flightCost, hotelNight, recDays, hotelCost, totalCost, climate: destData ? destData.climate_type : '' };
      }).sort((a, b) => a.totalCost - b.totalCost);

      atlas.analysis     = analysis;
      atlas.best_destination = analysis[0].destination_city;

      const medals   = ['🥇','🥈','🥉','4️⃣','5️⃣'];
      const table    = analysis.map((a, i) => `${medals[i] || `${i+1}.`} *${a.destination_city}, ${a.destination_country}*\n   💊 Procedimiento: ${usd(a.procedure_cost)}\n   ✈️ Vuelo estimado: ${usd(a.flightCost)}\n   🏨 Hotel (${a.recDays} noche${a.recDays>1?'s':''}): ${usd(a.hotelCost)}\n   💰 *TOTAL REAL: ${usd(a.totalCost)}*`).join('\n\n');

      const saving   = analysis.length > 1 ? analysis[analysis.length-1].totalCost - analysis[0].totalCost : 0;
      const best     = analysis[0];
      const recText  = saving > 0
        ? `✅ *${best.destination_city}* ofrece el mejor costo total, ahorrando *${usd(saving)}* vs la opción más cara.`
        : `✅ *${best.destination_city}* es tu mejor opción en costo total.`;

      rt = `📊 *Comparación de Destinos — Costo Total Real*\n*Procedimiento: ${sage.procedure_name || procType}*\n\n${table}\n\n${recText}\n\n¿Quieres ver el *checklist pre-viaje* para viajar a ${best.destination_city}? Escribe *checklist*.`;
    }
    break;
  }

  // ── ANÁLISIS DIRECTO (cotizaciones ya en DB) ────────────────
  case 'analyzing': {
    const quotes = allQuotes.length > 0 ? allQuotes : (atlas.quotes || []);
    if (quotes.length < 2) {
      rt = `Necesito al menos 2 cotizaciones para hacer la comparación${nm}. Actualmente tienes ${quotes.length}.\n\nEscribe una cotización en formato: *País - Ciudad - Precio*`;
      atlas.state = 'entering_quotes';
      break;
    }

    atlas.state = 'comparison_done';
    const analysis = quotes.map(q => {
      const destData  = destinations.find(d =>
        d.city.toLowerCase()    === (q.destination_city || '').toLowerCase()    ||
        d.country.toLowerCase() === (q.destination_country || '').toLowerCase()
      );
      const flightCost = parseFloat(destData ? destData.avg_flight_cost_usd          : 400);
      const hotelNight = parseFloat(destData ? destData.avg_hotel_cost_per_night_usd : 80);
      const recDays    = parseInt(destData   ? destData[recoveryField]               : 3);
      const hotelCost  = hotelNight * recDays;
      const totalCost  = parseFloat(q.procedure_cost) + flightCost + hotelCost;
      return { ...q, flightCost, hotelNight, recDays, hotelCost, totalCost };
    }).sort((a, b) => a.totalCost - b.totalCost);

    atlas.analysis        = analysis;
    atlas.best_destination = analysis[0].destination_city;

    const medals  = ['🥇','🥈','🥉','4️⃣','5️⃣'];
    const table   = analysis.map((a, i) => `${medals[i] || `${i+1}.`} *${a.destination_city}, ${a.destination_country}*\n   💊 Procedimiento: ${usd(a.procedure_cost)}\n   ✈️ Vuelo estimado: ${usd(a.flightCost)}\n   🏨 Hotel (${a.recDays} noche${a.recDays>1?'s':''}): ${usd(a.hotelCost)}\n   💰 *TOTAL REAL: ${usd(a.totalCost)}*`).join('\n\n');

    const saving  = analysis.length > 1 ? analysis[analysis.length-1].totalCost - analysis[0].totalCost : 0;
    const recText = saving > 0
      ? `✅ *${analysis[0].destination_city}* es la opción más económica, ahorrando *${usd(saving)}* vs la más cara.`
      : `✅ *${analysis[0].destination_city}* es tu mejor opción.`;

    rt = `📊 *Análisis de Costos Totales*\n\n${table}\n\n${recText}\n\nEscribe *checklist* para ver la lista de preparación para viajar a ${analysis[0].destination_city}.`;
    break;
  }

  // ── ANÁLISIS COMPLETO ────────────────────────────────────────
  case 'comparison_done': {
    const wantsChecklist = /checklist|lista|preparar|qué llev|llevar|documentos|preparacion/i.test(txt);
    const wantsMore      = /más cotizac|otra cotizac|agregar|nueva/i.test(txt);
    const wantsSage      = /sage|nueva solicitud|otro procedimiento/i.test(txt);
    const best           = atlas.best_destination || 'el destino elegido';

    if (wantsChecklist) {
      atlas.state = 'checklist_shown';
      const baseItems = [
        '📋 Pasaporte vigente (mínimo 6 meses de validez)',
        '📄 Historial médico relevante (diagnósticos, cirugías previas)',
        '💊 Lista completa de medicamentos actuales',
        '💳 Tarjeta de crédito/débito con cupo internacional',
        '📱 Seguro de viaje con cobertura médica (altamente recomendado)',
        '🏨 Reserva de hotel confirmada cerca de la clínica',
        '✈️ Vuelos con fecha de retorno flexible (en caso de complicaciones)',
        '📞 Contacto de emergencia notificado del viaje'
      ];
      const dentalItems = [
        '🦷 Radiografías recientes (panorámica y/o periapicales)',
        '📷 Fotografías de la boca/sonrisa (frente y perfil)',
        '⏰ Coordinar estadía mínima de 3-7 días según procedimiento',
        '🚫 Evitar fumar 48h antes del procedimiento dental'
      ];
      const plasticItems = [
        '📸 Fotografías corporales: frente, perfil y 3/4',
        '🩺 Exámenes preoperatorios completos (sangre, coagulación, ECG)',
        '⏰ Coordinar estadía mínima de 14-21 días para recuperación segura',
        '👕 Ropa cómoda y holgada para el período post-operatorio',
        '🚫 No fumar durante al menos 2 semanas antes de la cirugía',
        '💊 Informar todos los medicamentos y suplementos al cirujano'
      ];
      const extra = procType === 'dental' ? dentalItems : plasticItems;
      const allItems = [...baseItems, ...extra].map((item, i) => `${i+1}. ${item}`).join('\n');

      rt = `✅ *Checklist Pre-Viaje — ${best}*\n*Procedimiento: ${sage.procedure_name || procType}*\n\n${allItems}\n\n⚠️ *Importante:* Confirma los requisitos específicos con tu médico al agendar. Esta lista es orientativa.\n\n¿Hay algo más en lo que pueda ayudarte?`;
    } else if (wantsMore) {
      atlas.state = 'entering_quotes';
      rt = `Claro${nm}, ingresa la nueva cotización:\n*País - Ciudad - Precio*`;
    } else if (wantsSage) {
      rt = `Por supuesto${nm}. Te conecto con *SAGE* 🩺 para preparar una nueva solicitud de cotización.`;
      nag = 'SAGE';
      nss = 'handoff_received';
      atlas.state = 'handoff_to_sage';
    } else {
      rt = `¿En qué más puedo ayudarte${nm}?\n\n📋 Escribe *checklist* — Lista de preparación para ${best}\n📊 Escribe *nueva cotización* — Agregar otra cotización a la comparación\n🩺 Escribe *sage* — Preparar nueva solicitud de cotización`;
    }
    break;
  }

  // ── CHECKLIST MOSTRADO ──────────────────────────────────────
  case 'checklist_shown': {
    rt = `¿Tienes alguna pregunta adicional sobre el viaje médico a ${atlas.best_destination || 'tu destino elegido'}${nm}? 🗺️\n\nEstoy aquí para ayudarte en lo que necesites.`;
    break;
  }

  // ── FALLBACK ────────────────────────────────────────────────
  default: {
    rt = `Hola${nm}, soy *ATLAS* 🗺️ tu consejero de turismo médico. Escribe *1* si tienes cotizaciones o *2* para explorar destinos.`;
    atlas.state = 'welcome';
  }
}

// ── RESULTADO ──────────────────────────────────────────────
return [{ json: {
  success:           true,
  responseText:      rt,
  newActiveAgent:    nag,
  newSessionState:   nss,
  newAtlasContext:   atlas,
  inputContext:      ctx,
  userId:            parseInt(inp.userId),
  sessionId:         parseInt(inp.sessionId),
  userLanguage:      inp.userLanguage || 'es',
  userName:          inp.userName    || null,
  remoteJid:         inp.remoteJid,
  instance:          inp.instance
}}];

// ============================================================
// Construye la respuesta final de ATLAS.
// Ensambla newSessionContext con el atlas context actualizado.
// ============================================================

const motor = $input.first().json;

if (!motor.success) {
  return [{ json: {
    success:        false,
    error:          motor.error || 'ATLAS_ENGINE_ERROR',
    responseText:   'Error interno en ATLAS. Por favor escribe de nuevo.',
    newActiveAgent: 'ATLAS'
  }}];
}

const newSessionContext = {
  ...(motor.inputContext || {}),
  atlas: motor.newAtlasContext
};

return [{ json: {
  success:            true,
  responseText:       motor.responseText,
  newActiveAgent:     motor.newActiveAgent  || 'ATLAS',
  newSessionState:    motor.newSessionState || 'atlas_active',
  newSessionContext,
  userId:             motor.userId,
  sessionId:          motor.sessionId,
  userLanguage:       motor.userLanguage    || 'es',
  userName:           motor.userName        || null,
  remoteJid:          motor.remoteJid,
  instance:           motor.instance
}}];

const e = $input.first().json;
return [{ json: {
  success:        false,
  error:          e.error   || 'ATLAS_ENGINE_ERROR',
